// HasJobResource applies the HasEdge predicate on the "job_resource" edge.
func HasJobResource() predicate.JobRound {
	return predicate.JobRound(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, JobResourceTable, JobResourceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasJobResourceWith applies the HasEdge predicate on the "job_resource" edge with a given conditions (other predicates).
func HasJobResourceWith(preds ...predicate.JobResource) predicate.JobRound {
	return predicate.JobRound(func(s *sql.Selector) {
		step := newJobResourceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.JobRound) predicate.JobRound {
	return predicate.JobRound(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.JobRound) predicate.JobRound {
	return predicate.JobRound(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.JobRound) predicate.JobRound {
	return predicate.JobRound(sql.NotPredicates(p))
}
